uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// User Parameters
uniform float u_speed;
uniform float u_twist; 
uniform float u_hue;   // Base Color
uniform float u_hue2;  // Rainbow Spread
uniform float u_glow;  // Neon Glow Intensity
uniform float u_glitch; // Spacewave Glitchiness

out vec4 fragColor;

// --- Helper Functions ---

vec3 hsb2rgb(vec3 c) {
    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    rgb = rgb * rgb * (3.0 - 2.0 * rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

// Neon Palette Logic
vec3 getNeonColor(float hue, float z) {
    // High saturation for neon feel
    float sat = 0.9; 
    float bri = 1.0; 
    return hsb2rgb(vec3(fract(hue), sat, bri));
}

float hash(float n) { return fract(sin(n) * 43758.5453123); }

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // Glitch / Spacewave distortion
    float glitchTrigger = step(0.98, hash(iTime * 10.0)) * u_glitch;
    uv.x += (hash(floor(uv.y * 10.0) + iTime) - 0.5) * 0.05 * glitchTrigger;

    // Params
    float spd = (u_speed <= 0.0) ? 0.3 : u_speed;
    float time = iTime * spd;
    float twistAmt = u_twist; 

    // --- PETAL ANIMATION (Smooth Morph) ---
    float rawPetals = 4.0 + 4.0 * sin(iTime * 0.2);
    float p1 = floor(rawPetals);      
    float p2 = p1 + 1.0;              
    float blend = fract(rawPetals);   

    // --- HUE ANIMATION ---
    float baseHue = u_hue;
    float spread = u_hue2; 
    float animHue = baseHue + iTime * 0.1; 

    // Background - Deep Space Purple
    vec3 finalColor = vec3(0.01, 0.0, 0.02);

    float angle = atan(uv.y, uv.x);
    float radius = length(uv);

    const int LAYERS = 50; 

    for(int i = LAYERS; i > 0; i--) {
        float zIndex = float(i) - fract(time * 1.2); 
        float z = zIndex * 0.18; 

        if(z < 0.05) continue; 

        float projection = 1.0 / z;

        // --- VORTEX SHAPE ---
        // Add a bit of pulse to the twist for spacewave feel
        float currentAngle = angle + z * (twistAmt + sin(time * 0.5) * 0.5) + time * 0.8;

        // Morph Blend Waves
        float wave1 = sin(currentAngle * p1);
        float wave2 = sin(currentAngle * p2);
        float wave = mix(wave1, wave2, smoothstep(0.0, 1.0, blend));

        // Secondary interference for technical/synth look
        wave += sin(currentAngle * 10.0 + time) * 0.05;

        float ringRadius = 0.6 + 0.15 * wave;
        float screenRadius = ringRadius * projection * 0.35;

        // --- Visuals ---
        float dist = abs(radius - screenRadius);
        // Sharper thickness for neon lines
        float thickness = 0.005 * projection; 

        float lineGlow = exp(-dist / (thickness * 1.5)) * u_glow;
        float fog = smoothstep(0.0, 0.8, projection); 

        // --- COLOR CALCULATION ---
        float layerHue = animHue + z * spread;
        vec3 col = getNeonColor(layerHue, z);

        // Add flickering/scanline effect
        float scanline = mix(1.0, 0.5 + 0.5 * sin(uv.y * 400.0 + iTime * 20.0), 0.2);

        // Composition
        finalColor += col * lineGlow * fog * scanline;

        // Occasional brighter "data peaks"
        if(hash(float(i) + floor(time)) > 0.95) {
            finalColor += col * exp(-dist / (thickness * 10.0)) * 0.2 * fog;
        }
    }

    // Grid floor simulation for Spacewave
    if(uv0.y < -0.1) {
        float horizon = abs(1.0 / (uv0.y + 0.1));
        float grid = sin(uv0.x * 20.0 * horizon) * sin(horizon + time * 5.0);
        grid = smoothstep(0.7, 1.0, grid);
        finalColor += vec3(0.0, 0.8, 1.0) * grid * 0.1 * (1.0 / horizon);
    }

    // Center Sun/Glow
    float farHue = animHue + 2.0 * spread;
    vec3 sunCol = hsb2rgb(vec3(fract(farHue - 0.1), 0.8, 1.0));
    float sun = exp(-radius * 8.0);
    finalColor += sunCol * sun * 1.5;

    // VHS Vignette and noise
    float vig = smoothstep(1.5, 0.2, length(uv0));
    finalColor *= vig;
    finalColor += (hash(uv.x + uv.y + iTime) - 0.5) * 0.02;

    // Color Grading
    finalColor = pow(finalColor, vec3(0.8)); // Punchier colors
    fragColor = vec4(finalColor, 1.0);
}

